// Validate filename first
let sanitized = filename.replacingOccurrences(of: "../", with: "")
    .replacingOccurrences(of: "..\", with: "")
guard let url = base?.appendingPathComponent(sanitized) else { throw ModelDownloadError.invalidURL }

struct SecureString: ~Copyable {
    private var buffer: ContiguousArray<UInt8>
    private var decrypted: Bool = false

    init(from string: String) {
        buffer = ContiguousArray(string.utf8)
        // XOR with random key for memory obfuscation
        buffer = buffer.map { $0 ^ 0xA5 }
    }

    consuming func withSecureAccess<T>(_ operation: (String) throws -> T) rethrows -> T {
        var temp = buffer.map { $0 ^ 0xA5 }
        defer {
            for i in temp.indices { temp[i] = 0 }
        }
        let string = String(bytes: temp, encoding: .utf8)!
        return try operation(string)
    }

    deinit {
        for i in buffer.indices { buffer[i] = 0 }
    }
}

var secureAPIKey: SecureString? {
    guard let key = keychain.apiKey else { return nil }
    return SecureString(from: key)
}

// Usage in service
apiKey.withSecureAccess { key in
    request.setValue(key, forHTTPHeaderField: "Authorization")
}

private let secureAPIKey: SecureString

init(apiKey: String) {
    self.secureAPIKey = SecureString(from: apiKey)
}

// In API calls:
secureAPIKey.withSecureAccess { key in
    var request = URLRequest(url: url)
    request.setValue(key, forHTTPHeaderField: "Authorization")
    // ... execute request
}
